arguments.old:
// 45 deg chamfers on the two crown side edges, limited to the central
// contact zone |x| <= 36. Each box is the half-space beyond its
// chamfer plane, rotated -45 deg about X from an origin on the plane:
//   far side keeps Y + Z <= hang_top_z(36) + hang_width
//   bed side keeps Y - Z <= hang_top_z(36)
// At |x| = 36 the crown meets the plane, so beyond it the plate keeps
// its full 34 mm width; at the centre the chamfers leave a ~30.7 mm
// flat crown. The bed-side chamfer face itself is exactly 45 deg.
translate([0, hang_top_z(36), hang_width]) rotate([-45, 0, 0])
    translate([-36, 0, 0]) cube([72, 40, 40]);
translate([0, hang_top_z(36), 0]) rotate([-45, 0, 0])
    translate([-36, 0, 0]) cube([72, 40, 40]);

arguments.new:
// 45 deg chamfers on the two crown side edges, tangent to the crown
// arc at |x| = 26 (hang_top_z(26) = crown - 2.0 mm). Each box is the
// half-space beyond its chamfer plane, rotated -45 deg about X from
// an origin on the plane:
//   far side keeps Y + Z <= hang_top_z(26) + hang_width
//   bed side keeps Y - Z <= hang_top_z(26)
// Beyond |x| = 26 the plate keeps its full 34 mm width; at the crown
// the two 45 deg breaks leave a 30.0 mm wide flat top (>= 30 mm for
// the headband), and the arc gives the rounded profile. The bed-side
// chamfer face itself is exactly 45 deg, so no supports are needed.
translate([0, hang_top_z(26), hang_width]) rotate([-45, 0, 0])
    translate([-26, 0, 0]) cube([52, 40, 40]);
translate([0, hang_top_z(26), 0]) rotate([-45, 0, 0])
    translate([-26, 0, 0]) cube([52, 40, 40]);
